"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2852],{43413:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"Packets","desc":"Typed network packet registry. All client\u2194server traffic in the game\\ngoes through packets defined here \u2014 do **not** use raw `RemoteEvent`\\ninstances for new channels. Reliable packets use `Packet(name, ...)`\\ndirectly; high-frequency positional packets (ghost updates) use\\n`makeUnreliable` which wraps an `UnreliableRemoteEvent` for lower\\nlatency.\\n\\nThe full networking map (direction, payload types, and which scripts\\nsend/receive each packet) lives in the Reference \u2192 Networking map in\\n`Documentations/Project-Maintenance-Guide.md`. Register new packets\\nthere whenever you add one here.","source":{"line":937,"path":"src/ReplicatedStorage/SharedModules/Packets/init.luau"}}')}}]);